TI=[]
def T(a,t,c,k,r,cmd=''):TI.append((a,t,c.split('|'),k.split('|'),r.split('|'),cmd))
T('Compute','VM not reachable','VM not running|NSG denies the port|UDR or firewall drops traffic|Wrong or missing public IP|DNS resolves to the wrong IP|JIT access not requested|OS firewall or app not listening','VM → Overview: status Running and the IPs|VM → Networking: inbound rules and Effective security rules|Network Watcher → Connection troubleshoot and IP flow verify|NIC → Help → Effective routes|Defender for Cloud → JIT: request access|VM → Help → Boot diagnostics and Serial console','Start the VM if stopped.|Add an allow rule with a lower priority number than the deny.|Fix the UDR next hop or firewall rule.|Request JIT access for your IP.|Open the OS firewall or start the service from Serial console or Run command.|Last resort: VM → Help → Redeploy + reapply.','Test-NetConnection <ip> -Port 3389   # Windows\nsudo ss -tlnp | grep :22        # Linux')
T('Compute','Disk full','Log growth|Temp or page files|OS disk too small|Data disk full','Monitor → Metrics or VM Insights: logical disk free space|VM → Settings → Disks: sizes|Serial console or Bastion for OS checks','Delete or rotate large logs.|Deallocate the VM, open Disks → select disk → Size + performance → increase → Save, then start (online expansion only on supported disks).|Extend the partition and filesystem inside the OS.|Add an alert on low free space.','df -h\nsudo du -xh / --max-depth=1 | sort -h | tail\nsudo journalctl --vacuum-size=500M\nGet-PSDrive C   # PowerShell')
T('Compute','High CPU','Runaway process|VM too small|B-series credits exhausted|Traffic spike|Malware or crypto-miner','Monitor → Metrics: Percentage CPU (Max and Avg), CPU Credits Remaining|VM → Insights → Performance|Activity log: recent changes','Find and fix the process.|Scale up: VM → Size (restart needed), or out with a scale set and load balancer.|Move from B-series to D-series for sustained load.|Add autoscale and a CPU alert.','top -o %CPU\nGet-Process | Sort-Object CPU -Descending | Select-Object -First 5')
T('Compute','VM deployment or start fails','Quota exceeded|Size or zone not available|Policy denied|Allocation failure|Extension error','Resource group → Deployments → failed deployment → error details|Subscriptions → Usage + quotas|Activity log for the failed operation','Request a quota increase.|Try another size, zone or region.|Review the Policy assignment named in the error.|Deallocate then start to move the VM to new hardware.')
T('Networking','Private endpoint not working','Private DNS zone not linked|Connection pending|Name still resolves to public IP|NSG or UDR blocks','Private endpoint → Connection state is Approved|Private DNS zone → Virtual network links|Run nslookup from a VM in the VNet|Network Watcher → IP flow verify','Link the zone to the VNet.|Approve the connection on the target.|Forward custom DNS to Azure DNS 168.63.129.16.|Fix NSG or UDR.','nslookup <account>.blob.core.windows.net')
T('Networking','VNet peering or VPN not working','Overlapping address space|Peering not Connected on both sides|Gateway transit not set|Shared key mismatch|On-premises device settings','VNet → Peerings: both Connected|Connection resource → status|Gateway → Diagnose and solve problems|Effective routes on the NIC','Fix address space and recreate the peering.|Enable allow gateway transit and use remote gateway correctly.|Reset the shared key to match.|Reset the gateway only as a last resort.')
T('Networking','Outbound internet fails or wrong source IP','UDR to firewall without allow rule|NAT gateway not associated|NSG outbound deny|DNS failure','NIC → Effective routes|Firewall logs: application and network rules|NAT gateway → Subnets|NSG outbound rules','Add the firewall rule.|Associate the NAT gateway with the subnet.|Correct the route or NSG.')
T('Networking','Load balancer or Application Gateway backend unhealthy','Probe port or path wrong|NSG blocks AzureLoadBalancer or GatewayManager|App down|Certificate or host header mismatch','Load balancer → Metrics: health probe status|Application Gateway → Monitoring → Backend health|NSG rules on the backend subnet','Fix the probe settings.|Allow the AzureLoadBalancer tag; for Application Gateway v2 allow GatewayManager on 65200-65535.|Restart or fix the app.|Match certificate and host name.')
T('Storage','403 authorization errors','Firewall blocks your IP or VNet|Missing data-plane role|SAS expired or wrong scope|Key rotated|Clock skew','Storage account → Networking: allowed IPs and VNets|Access control (IAM): Storage Blob Data role|Diagnostic logs for the failing request|Check the SAS expiry','Add the IP or VNet rule.|Assign Storage Blob Data Reader or Contributor.|Generate a new SAS.|Update apps with the new key.','StorageBlobLogs\n| where StatusCode == 403\n| project TimeGenerated, OperationName, CallerIpAddress, AuthenticationType, StatusText\n| take 50')
T('Storage','Slow performance or throttling','Account or partition limits|Cross-region access|Many small operations|Wrong performance tier','Metrics: Transactions by response type (ServerBusy), Success E2E latency|Storage Insights','Spread load across prefixes or accounts.|Co-locate the app in the same region.|Batch operations.|Use Premium or a CDN where suitable.')
T('Storage','Recover deleted or changed data','Soft delete or versioning off|Retention expired','Container → Show deleted blobs|Data protection settings|Blob → Versions','Undelete the blob or container.|Promote a previous version.|Use point-in-time restore if versioning, change feed and soft delete were on.|Enable these protections now.')
T('Identity','User cannot sign in','Wrong or expired password|Blocked by Conditional Access|MFA not registered|Account disabled|Missing license','Entra ID → Monitoring → Sign-in logs: status and failure reason|Open the Conditional Access tab on the event|Users → user → Authentication methods','Reset the password.|Fix or exclude the user in the policy (never the break-glass account).|Require MFA registration or reset methods.|Enable the account.')
T('Identity','AuthorizationFailed in Azure','No role at the scope|Deny assignment|Policy denial|Role not yet propagated|Wrong tenant or subscription','Resource → Access control (IAM) → Check access|Look at role assignments on parent scopes|Activity log error details|Switch directory and subscription filters','Assign a least-privilege role at the right scope.|Wait a few minutes; sign out and in.|Resolve policy or deny assignment.','az role assignment list --assignee <object-id> --all -o table')
T('Identity','App sign-in errors (AADSTS)','7000215 invalid secret|50011 redirect URI mismatch|700016 app not found in tenant|65001 consent needed','Sign-in logs: error code|App registration → Authentication and Certificates & secrets|API permissions: consent status','Create a new secret and update the app.|Add the exact redirect URI.|Use the correct tenant or multi-tenant setting.|Grant admin consent.')
T('Identity','PIM activation fails','Not eligible|MFA or approval required|Outside assignment window|License missing','PIM → My roles → Eligible assignments|PIM → Audit history','Ask an admin to assign eligibility.|Complete MFA or wait for approval.|Check start and end dates.')
T('Monitoring','Alert did not fire','Wrong signal or threshold|Rule disabled|Alert processing rule suppressing|Action group missing or broken','Monitor → Alerts → Alert rules: enabled|Metrics chart for the same signal and time|Alert processing rules|Action group → Test','Correct the condition.|Enable the rule.|Adjust the processing rule.|Fix recipients and retest.')
T('Monitoring','No logs in Log Analytics','Diagnostic setting missing|Agent or DCR not associated|Ingestion delay|Daily cap reached','Resource → Diagnostic settings|Data collection rule → Resources|Workspace → Usage and estimated costs → Daily cap','Add the diagnostic setting.|Install Azure Monitor Agent and associate the DCR.|Wait a few minutes.|Raise or remove the cap.','Heartbeat\n| summarize LastHeartbeat = max(TimeGenerated) by Computer')
T('Monitoring','Log Analytics cost too high','Verbose categories|Chatty tables|Long retention','Workspace → Usage and estimated costs','Disable unused categories.|Filter at the DCR.|Use Basic logs or shorter retention.','Usage\n| where IsBillable == true\n| summarize GB = sum(Quantity) / 1000 by DataType\n| sort by GB desc')
T('Backup','Backup job failed','VM agent unhealthy|VM stopped or extension error|Lock on the resource group|Storage or snapshot issue','Vault → Monitoring → Backup jobs: error code|VM → Extensions (VMSnapshot)|Resource group → Locks','Update or reinstall the VM agent.|Start the VM and retry.|Remove the lock on the AzureBackupRG restore point group.|Select Backup now to retest.')
T('Backup','Cannot delete a Recovery Services vault','Protected items remain|Soft-deleted items|Replicated items|Private endpoints','Vault → Backup items and Replicated items|Soft deleted items view','Stop protection and delete data.|Undelete, then delete soft-deleted items.|Disable replication.|Remove private endpoints.')
T('Backup','Site Recovery replication unhealthy','Agent or provider issue|Network or NSG blocks|Quota in target|Source disk change rate too high','Vault → Replicated items → health and errors|Site Recovery jobs','Fix the listed error and select Resynchronize.|Allow required outbound access.|Raise target quota.')
T('Security','Key Vault forbidden','Wrong permission model|Missing data role|Firewall|Private endpoint DNS','Key vault → Access configuration: model|IAM: Key Vault Secrets User or Officer|Networking: allowed access','Assign the data-plane role.|Add the IP or use a private endpoint.|Fix DNS.')
T('Security','JIT request denied or option missing','No Defender for Servers Plan 2|No initiate permission|NSG priority overrides|VM not onboarded','Defender plans: Servers Plan 2 on|Your role for jitNetworkAccessPolicies|NSG rule priorities','Enable the plan.|Grant the role.|Place the JIT rule above conflicting rules.')
T('Security','Suspected compromised account','Password spray or phishing|Leaked secret','Sign-in logs: unusual location and IP|Defender for Cloud alerts|Audit logs','Reset the password and revoke sessions.|Require MFA.|Rotate affected secrets and review role assignments.|Review alerts and activity.')
import collections
byA=collections.OrderedDict()
for i,x in enumerate(TI):byA.setdefault(x[0],[]).append((i,x))
li=lambda a,o='ul':f'<{o}>'+''.join(f'<li>{E(x)}</li>' for x in a)+f'</{o}>'
H='<div class="chips">'+''.join(f'<a href="#trouble" data-t="tsa-{a}">{a}</a>' for a in byA)+'</div>'
for a,l in byA.items():
    H+=f'<h2 id="tsa-{a}">{a} troubleshooting</h2>'
    for i,(_,t,c,k,r,cm) in l:
        H+=f'<details class="issue" id="ts-{i}"><summary>{t}</summary><h4>Possible causes</h4>{li(c)}<h4>Portal checks</h4>{li(k,"ol")}'+(f'<h4>Commands and queries</h4><pre class="cmd">{E(cm)}</pre>' if cm else '')+f'<h4>Resolution</h4>{li(r,"ol")}</details>'
ts_html=H+'<h2>Checks by SOP</h2>'+ts_html
